/* External numerical comparison: a transparent implementation check, never field validation. */
(() => {
  const host=document.querySelector('#mod-evaluation');if(!host)return;
  const zh=()=>document.documentElement.lang==='zh-Hant';
  const t=()=>zh()?{title:'外部模型交叉驗算',lead:'比較 HEC-HMS 或 SWMM 的已執行結果與目前 Software I 路由結果。兩者必須使用相同入流、初始水位、蓄水量—水位關係、出口定律與係數。此功能屬數值／實作交叉驗算，並非現地驗證。',source:'外部模型',basis:'比較尺度',raw:'直接工程單位（秒、m³/s、m、m³）',scaled:'實驗室時間尺度基準（模型分鐘與縮放流量；尺度 = 240）',file:'匯入 CSV 結果檔',run:'比較外部結果',format:'可辨識欄位：time_s（或 time／t；尺度模式則 model_time_min）、outflow_m3_s（或 qout／qo；尺度模式則 scaled_outflow_m3_s）；可選 relative_head_m（或 h／stage）與 incremental_storage_m3（或 s／storage）。第一列必須為欄名。',missing:'請先執行 Software I 路由，並匯入有效 CSV 檔。',invalid:'CSV 至少須有兩筆時間遞增且可辨識的出流資料。',failed:'比較未完成：',result:'交叉驗算結果',pass:'通過數值一致性判定',warn:'未通過預設數值一致性判定',q:'出流尖峰相對誤差',time:'出流尖峰時間差',h:'最大水位相對誤差',s:'最大蓄水量相對誤差',na:'未提供',note:'判定門檻：出流尖峰、最大水位與最大蓄水量相對誤差均 ≤ 0.5%，且尖峰時間差 ≤ 2 秒。未提供水位或蓄水量欄位者不以該項判定。通過僅表示此組輸入與外部執行結果在比較尺度上相符；不取代實驗室或現地驗證。'}:{title:'External-model cross check',lead:'Compare an executed HEC-HMS or SWMM result with the current Software I routing result. Both runs must use the same inflow, initial level, storage–level relation, outlet law and coefficients. This is a numerical / implementation cross check, not field validation.',source:'External model',basis:'Comparison basis',raw:'Direct engineering units (s, m³/s, m, m³)',scaled:'Laboratory time-scaled benchmark (model minutes and scaled discharge; scale = 240)',file:'Import result CSV',run:'Compare external result',format:'Recognized columns: time_s (or time/t; model_time_min in scaled mode), outflow_m3_s (or qout/qo; scaled_outflow_m3_s in scaled mode); optional relative_head_m (or h/stage) and incremental_storage_m3 (or s/storage). The first row must be headers.',missing:'Run Software I first and import a valid CSV file.',invalid:'The CSV needs at least two increasing-time rows with a recognized outflow.',failed:'Comparison did not complete: ',result:'Cross-check result',pass:'Numerical-consistency criterion passed',warn:'Default numerical-consistency criterion not passed',q:'Peak-outflow relative error',time:'Peak-outflow time difference',h:'Maximum-level relative error',s:'Maximum-storage relative error',na:'not supplied',note:'Criteria: relative errors of peak outflow, maximum level and maximum storage ≤ 0.5%, and peak-time difference ≤ 2 s. A missing level or storage column is excluded from that criterion. A pass means only that this input set agrees with the external execution at the comparison scale; it does not replace laboratory or field validation.'};
  const box=document.createElement('section');box.className='chart';box.id='crossModelBox';host.appendChild(box);
  const find=(row,names)=>names.find(k=>Object.hasOwn(row,k));const n=v=>Number(String(v??'').trim());const peak=(a,k)=>a.reduce((m,z)=>z[k]>m[k]?z:m,a[0]);const pct=(a,b)=>100*Math.abs(a-b)/Math.max(Math.abs(a),1e-12);
  const load=file=>file.text().then(raw=>{const rows=raw.replace(/^\uFEFF/,'').trim().split(/\r?\n/).filter(Boolean),sep=rows[0]?.includes('\t')?'\t':',';if(rows.length<3)throw Error(t().invalid);const head=rows[0].split(sep).map(x=>x.trim().toLowerCase());return rows.slice(1).map(line=>Object.fromEntries(head.map((h,i)=>[h,line.split(sep)[i]])));});
  function render(){const x=t();box.innerHTML=`<h3>${x.title}</h3><p class="meta">${x.lead}</p><div class="twocol"><div><label>${x.source}</label><select id="crossSource"><option>HEC-HMS</option><option>SWMM</option></select></div><div><label>${x.basis}</label><select id="crossScale"><option value="raw">${x.raw}</option><option value="scaled">${x.scaled}</option></select></div></div><label>${x.file}</label><input id="crossFile" type="file" accept=".csv,.txt,text/csv,text/plain"><p class="meta">${x.format}</p><button class="report" id="crossRun">${x.run}</button><div class="status hide" id="crossOut"></div>`;box.querySelector('#crossRun').addEventListener('click',compare);}
  async function compare(){const x=t(),out=box.querySelector('#crossOut'),file=box.querySelector('#crossFile').files[0];try{if(!last||!file)throw Error(x.missing);const scaled=box.querySelector('#crossScale').value==='scaled',raw=await load(file),f=raw[0],tk=find(f,scaled?['model_time_min','time_min','time']:['time_s','time','t']),qk=find(f,scaled?['scaled_outflow_m3_s','outflow_m3_s','qout','qo']:['outflow_m3_s','qout','qo','outflow']),hk=find(f,['relative_head_m','h','stage','water_level_m']),sk=find(f,['incremental_storage_m3','s','storage','storage_m3']);if(!tk||!qk)throw Error(x.invalid);const ext=raw.map(z=>({t:scaled?n(z[tk])*15:n(z[tk]),qo:scaled?n(z[qk])*240:n(z[qk]),h:hk?n(z[hk]):null,s:sk?n(z[sk]):null})).filter(z=>Number.isFinite(z.t)&&Number.isFinite(z.qo));if(ext.length<2||ext.some((z,i)=>i&&z.t<=ext[i-1].t))throw Error(x.invalid);const ref=last.r.rows,pr=peak(ref,'qo'),pe=peak(ext,'qo'),qerr=pct(pr.qo,pe.qo),terr=Math.abs(pr.t-pe.t),hasH=hk&&ext.every(z=>Number.isFinite(z.h)),hasS=sk&&ext.every(z=>Number.isFinite(z.s)),relativeH=hk==='relative_head_m',relativeS=sk==='incremental_storage_m3',hRef=peak(ref,'h').h-(relativeH?ref[0].h:0),sRef=peak(ref,'s').s-(relativeS?ref[0].s:0),herr=hasH?pct(hRef,peak(ext,'h').h):null,serr=hasS?pct(sRef,peak(ext,'s').s):null,pass=qerr<=.5&&terr<=2&&(herr===null||herr<=.5)&&(serr===null||serr<=.5),v=(a,u='%')=>a===null?x.na:a.toFixed(3)+u;out.className='status '+(pass?'':'warn');out.innerHTML=`<strong>${x.result} — ${pass?x.pass:x.warn}</strong><table class="metrics"><tr><th>${x.q}</th><td>${v(qerr)}</td></tr><tr><th>${x.time}</th><td>${terr.toFixed(2)} s</td></tr><tr><th>${x.h}</th><td>${v(herr)}</td></tr><tr><th>${x.s}</th><td>${v(serr)}</td></tr></table><p class="meta">${x.note}</p>`;}catch(e){out.className='status stop';out.innerHTML='<strong>'+x.failed+'</strong>'+e.message;}}
  render();document.getElementById('lang')?.addEventListener('click',()=>setTimeout(render,0));
})();
